import dcomputeInertia = require( './index' );


// TESTS //

// The function returns a number...
{
	const X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
	const C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
	const labels = new Int32Array( [ 0, 1 ] );

	dcomputeInertia( 'row-major', 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
	const C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
	const labels = new Int32Array( [ 0, 1 ] );

	dcomputeInertia( 5, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( true, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( false, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( null, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( void 0, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( [], 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( {}, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
	dcomputeInertia( ( x: number ): number => x, 2, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 ); // $ExpectError
}

